/*
 * candled_conf.h -- the configuration of candled(8): what candled.conf(5) says.
 *
 * The file is read by the parser in candled_conf.c, which was generated by hbnf from
 * grammars/candled.hbnf (see HACKING); the build does not need hbnf.
 */
#ifndef CANDLED_CONF_H
#define CANDLED_CONF_H

#include <stddef.h>

/* The file names and the like are allocated; candled_conf_free releases them.  A value that is
 * NULL (or, for the flags, -1) was not set by the file, so a command-line option or a default
 * can stand. */
struct candled_conf {
    char   *listen_addr;               /* an IPv4 address (default 127.0.0.1) */
    int     port;                      /* 0: not set (default 8766) */
    int     tls;                       /* 1 yes, 0 no, -1 not set (default yes) */
    int     insecure;                  /* 1: plain HTTP is allowed on a non-loopback address; -1 not set */
    int     official_klines;           /* -1 not set */
    char   *certificate, *key;         /* the server's certificate and private key (PEM) */
    char   *authorized;                /* the file of the clients' fingerprints */
    char  **authorize;                 /* fingerprints given in the file itself: "SHA256:<64 hex digits>" */
    size_t  nauthorize;
    char   *candles, *backfill, *database, *live_bins, *heat_db;
};

/* Fill in "not set" everywhere. */
void candled_conf_init(struct candled_conf *c);
void candled_conf_free(struct candled_conf *c);

/* Read the file into *c (which candled_conf_init has set up).  Returns 0, or -1 after having
 * printed every error as "file:line: message" on standard error. */
int candled_conf_parse(const char *path, struct candled_conf *c);

#endif /* CANDLED_CONF_H */
